# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, G, R = "Lucas", "Amparo", "Alejandra", "Rodolfo"
D = [
("#", "Escena 1 · 16:30 · Sala de reuniones, Onda", "장면 1 · 오후 4시 30분 · 온다, 회의실"),
(None, "Miércoles 12 de febrero. En la pantalla grande de la sala, un reloj doble: Onda 16:30, Monterrey 9:30. Sobre la mesa, dos piezas de muestra de la serie blanca, un portátil y tres tazas de café. Amparo entra con una carpeta bajo el brazo.", "2월 12일 수요일. 회의실 대형 화면에 시계 두 개가 떠 있다. 온다 16:30, 몬테레이 9:30. 테이블 위에는 흰색 시리즈 샘플 두 장, 노트북, 커피잔 세 개. 암파로가 서류철을 끼고 들어온다."),
(A, "¿A qué hora empieza la llamada?", "통화는 몇 시에 시작해요?"),
(L, "A las cinco nuestras. Allí serán las diez de la mañana.", "우리 시간 5시요. 거기는 오전 10시일 거예요."),
(A, "Siete horas de diferencia. Vamos a pasar muchas tardes así si esto sale.", "7시간 차이네. 이게 성사되면 이런 오후를 많이 보내겠군요."),
(L, "Gracias por venir. No tenías por qué.", "와 줘서 고마워요. 꼭 올 필요는 없었는데."),
(A, "Claro que tenía. Si prometes plazos, los plazos salen de mi almacén. Prefiero oírlos en directo.", "당연히 와야죠. 당신이 납기를 약속하면 그 납기는 내 창고에서 나오니까. 직접 듣는 게 나아요."),
(L, "Me parece justo. ¿Has traído los datos del lote?", "공정하네요. 로트 데이터 가져왔어요?"),
(A, "Aquí están. Del blanco en sesenta por ciento veinte tenemos unos dieciocho mil metros en stock. Calibre y tono homogéneos.", "여기요. 흰색 60×120은 재고가 1만 8천 제곱미터쯤 있어요. 치수와 색조는 균일하고요."),
(L, "Dieciocho mil. Ellos hablan de sesenta mil para la primera fase.", "1만 8천이라. 저쪽은 1단계에 6만을 얘기하는데요."),
(A, "Ya lo sé. Por eso no quiero que digas «tenemos todo en stock».", "알아요. 그래서 '전부 재고 있다'고 말하지 말라는 거예요."),
(L, "No lo diré. Diré que una parte se sirve de stock y el resto se fabrica bajo pedido.", "안 그럴게요. 일부는 재고에서 공급하고 나머지는 주문 생산한다고 할게요."),
(A, "Bien. ¿Y si preguntan por el plazo de fabricación?", "좋아요. 생산 기간을 물으면요?"),
(L, "Pepe me ha dicho que entre cuatro y seis semanas, según la carga de los hornos.", "페페 말로는 가마 부하에 따라 4주에서 6주래요."),
(A, "Di seis. Siempre es mejor llegar antes que tarde.", "6주라고 해요. 늦는 것보다 일찍 도착하는 게 늘 나아요."),
(L, "Apuntado. Y otra cosa: no sé si me van a preguntar por la norma mexicana.", "적었어요. 그리고 하나 더, 멕시코 규격에 대해 물어볼지 모르겠어요."),
(A, "Te la van a preguntar seguro. Las constructoras allí piden certificados para todo.", "분명히 물을 거예요. 거기 건설사들은 뭐든 인증서를 요구하니까."),
(L, "Entonces, si me preguntan, diré que lo compruebo y les contesto por escrito.", "그럼 물으면 확인해서 서면으로 답하겠다고 할게요."),
(A, "Eso sí. Y Lucas... no hables demasiado rápido. Allí hablan más despacio que en Madrid.", "그건 좋네요. 그리고 루카스… 너무 빨리 말하지 마요. 거기 사람들은 마드리드보다 천천히 말해요."),
(None, "Suena un pitido. En la pantalla aparecen dos caras: Alejandra Garza, en una oficina con ventanales, y un hombre joven con camisa de cuadros y casco blanco sobre la mesa.", "삐 소리가 난다. 화면에 두 얼굴이 나타난다. 통유리창이 있는 사무실의 알레한드라 가르사, 그리고 체크무늬 셔츠에 흰 안전모를 책상에 올려 둔 젊은 남자."),

("#", "Escena 2 · 17:00 (Monterrey 10:00) · Videollamada", "장면 2 · 오후 5시 (몬테레이 오전 10시) · 화상 통화"),
(G, "¡Buenos días, licenciado! Bueno, buenas tardes para ustedes, ¿verdad?", "안녕하세요, 선생님! 아, 그쪽은 오후 인사겠네요, 그렇죠?"),
(L, "Buenas tardes, señora Garza. Le presento a Amparo Albalat, directora de ventas nacionales.", "안녕하세요, 가르사 씨. 국내 영업 책임자 암파로 알발라트를 소개합니다."),
(A, "Encantada, señora Garza.", "반갑습니다, 가르사 씨."),
(G, "Mucho gusto, Amparo. Les presento al ingeniero Rodolfo Leal, nuestro jefe técnico. Él es el que va a revisar todo con lupa.", "반가워요, 암파로. 저희 기술 책임자 로돌포 레알 엔지니어를 소개할게요. 이 사람이 전부 돋보기로 살펴볼 거예요."),
(R, "Mucho gusto. Ya tengo las muestras aquí enfrente. Llegaron el lunes, todas enteras, gracias a Dios.", "반갑습니다. 샘플은 지금 제 앞에 있어요. 월요일에 왔는데 다행히 하나도 안 깨졌어요."),
(L, "Me alegro. ¿Qué primera impresión le han dado?", "다행이네요. 첫인상은 어떠셨어요?"),
(R, "Están muy bonitas, la verdad. La veta se ve muy natural. Pero yo soy ingeniero, a mí lo bonito no me paga la quincena.", "솔직히 아주 예뻐요. 결이 아주 자연스러워요. 근데 전 엔지니어라서 예쁜 게 월급을 주진 않거든요."),
(G, "(ríe) Rodolfo es así. Primero los números, luego los halagos.", "(웃으며) 로돌포는 원래 이래요. 숫자가 먼저고 칭찬은 나중이죠."),
(L, "Me parece perfecto. Pregunte lo que necesite.", "아주 좋습니다. 필요한 건 뭐든 물어보세요."),
(G, "Antes de empezar, licenciado, una curiosidad. ¿Ya se acostumbró a la fábrica? Me dijo que era nuevo.", "시작하기 전에, 선생님, 궁금한 게 하나 있어요. 공장엔 벌써 적응하셨어요? 새로 오셨다고 했잖아요."),
(L, "Llevo nueve días. Todavía me pierdo entre las naves, pero ya sé dónde está la máquina de café.", "9일째예요. 아직 공장동 사이에서 길을 잃지만 커피 자판기 위치는 알아요."),
(G, "Eso es lo más importante. (ríe) Ándale, Rodolfo, empieza tú.", "그게 제일 중요하죠. (웃으며) 자, 로돌포, 먼저 시작해요."),
(R, "Ándale. Primera pregunta: ¿qué absorción de agua tiene esta pieza?", "좋아요. 첫 번째 질문, 이 타일의 흡수율은 얼마죠?"),
(L, "Es porcelánico, así que la absorción es inferior al cero coma cinco por ciento.", "자기질 타일이라 흡수율이 0.5% 미만입니다."),
(R, "Okey. ¿Y está rectificada?", "오케이. 그럼 정밀 재단(렉티파이드)됐나요?"),
(L, "¿Rectificada? Sí... ¿Amparo?", "렉티파이드요? 네… 암파로?"),
(A, "Sí, está rectificada. Los cantos se cortan a máquina después de la cocción, para que la junta sea mínima.", "네, 렉티파이드예요. 소성 후에 모서리를 기계로 잘라서 줄눈을 최소로 할 수 있어요."),
(R, "Perfecto, porque el arquitecto quiere junta de dos milímetros. Ahora, la que más me preocupa: la resistencia al deslizamiento.", "좋네요, 건축가가 줄눈 2밀리를 원하거든요. 이제 제일 걱정되는 거요. 미끄럼 저항."),
(L, "¿Para qué zona sería exactamente?", "정확히 어느 구역용인가요?"),
(R, "Para el vestíbulo del hotel y para los baños de los departamentos. En el vestíbulo, la gente entra con los zapatos mojados cuando llueve.", "호텔 로비하고 아파트 욕실용이요. 로비엔 비 오면 사람들이 젖은 신발로 들어오니까요."),
(L, "Entiendo. ¿Me puede decir qué valor exige la constructora?", "알겠습니다. 건설사가 요구하는 수치가 얼마인지 말씀해 주시겠어요?"),
(R, "El coeficiente de fricción en mojado, mínimo cero punto seis para los baños. Para el vestíbulo, el arquitecto todavía no decide.", "젖은 상태 마찰계수가 욕실은 최소 0.6이요. 로비는 건축가가 아직 안 정했어요."),
(L, "Nuestro acabado pulido es muy elegante, pero en mojado no llega a ese valor. Tenemos una versión antideslizante del mismo diseño.", "저희 광택 마감은 아주 우아하지만 젖으면 그 수치가 안 나와요. 같은 디자인의 미끄럼 방지 버전이 있습니다."),
(G, "¿Del mismo diseño? ¿Se ve igual?", "같은 디자인이요? 똑같아 보여요?"),
(A, "Casi igual. El brillo es menor, pero la veta es la misma. Podemos mandarles una muestra.", "거의 같아요. 광택은 덜하지만 결은 같아요. 샘플을 보내 드릴 수 있어요."),
(G, "Sí, mándenos una, por favor. Pulido para el vestíbulo y antiderrapante para los baños. Así le gusta a todo el mundo.", "네, 하나 보내 주세요. 로비엔 광택, 욕실엔 미끄럼 방지. 그러면 다들 좋아하겠네요."),
(L, "¿Antiderrapante? Aquí decimos antideslizante, pero me lo apunto.", "안티데라판테요? 여기선 안티데슬리산테라고 하는데, 적어 둘게요."),
(R, "(sonríe) Va a terminar hablando como regiomontano, licenciado.", "(웃으며) 결국 몬테레이 사람처럼 말하게 되실 거예요, 선생님."),
(L, "Ojalá. Siguiente pregunta, ingeniero.", "그러면 좋겠네요. 다음 질문 주세요, 엔지니어님."),
(R, "Certificados. Aquí la constructora nos pide que el material cumpla con la norma mexicana. ¿Ustedes tienen pruebas de laboratorio?", "인증서요. 여기 건설사는 자재가 멕시코 규격을 충족해야 한대요. 시험성적서 있으세요?"),
(L, "Tenemos los ensayos según la norma europea, hechos por un laboratorio independiente aquí en Castellón. Lo que no sé es si son válidos en México.", "유럽 규격에 따른 시험은 여기 카스테욘의 독립 시험기관에서 받았습니다. 멕시코에서 유효한지는 모르겠어요."),
(R, "Pues hay que averiguarlo, porque sin eso la obra no lo acepta.", "그럼 알아봐야 해요. 그게 없으면 현장에서 안 받아 주거든요."),
(L, "Lo compruebo esta semana y le contesto por escrito. ¿Le parece bien?", "이번 주에 확인해서 서면으로 답드릴게요. 괜찮으세요?"),
(R, "Me parece muy bien. Siguiente: ¿cuánto pesa una caja?", "아주 좋아요. 다음, 한 박스 무게가 얼마예요?"),
(L, "Un momento... En sesenta por ciento veinte, cada caja lleva dos piezas, uno coma cuarenta y cuatro metros cuadrados, y pesa unos treinta y dos kilos.", "잠시만요… 60×120은 박스당 두 장, 1.44제곱미터이고 무게는 32킬로 정도예요."),
(R, "¿Y cuántas cajas van por tarima?", "그럼 타리마 하나에 몇 박스 들어가요?"),
(L, "¿Por tarima? Perdone, ¿qué es una tarima?", "타리마당이요? 죄송한데, 타리마가 뭐예요?"),
(G, "La tarima, licenciado, donde se apilan las cajas. ¿Cómo le dicen ustedes?", "타리마요, 선생님, 박스 쌓는 거요. 그쪽에선 뭐라고 해요?"),
(A, "El palé. Aquí decimos palé.", "팔레요. 여기선 팔레라고 해요."),
(L, "Gracias, Amparo. Van veintiocho cajas por palé. Unos cuarenta metros cuadrados.", "고마워요, 암파로. 팔레당 28박스요. 40제곱미터쯤이에요."),
(R, "Okey, entonces un contenedor de veinte pies lleva... ¿cuántos metros, más o menos?", "오케이, 그럼 20피트 컨테이너 하나엔… 대충 몇 제곱미터 들어가요?"),
(L, "Por el peso, alrededor de mil trescientos metros cuadrados. El contenedor se llena de peso antes que de volumen.", "무게 때문에 1,300제곱미터 안팎이에요. 컨테이너는 부피보다 무게가 먼저 차거든요."),
(R, "Ah, claro, es material pesado. Entonces para sesenta mil metros son como cuarenta y seis contenedores.", "아, 그렇죠, 무거운 자재니까. 그럼 6만 제곱미터면 컨테이너 46개 정도네요."),
(G, "Cuarenta y seis contenedores... Eso es un barco entero, Rodolfo.", "컨테이너 46개라… 그건 배 한 척 통째예요, 로돌포."),
(R, "Casi. Por eso hay que pensar bien en las entregas. Licenciado, ¿cuál sería el tiempo de entrega?", "거의 그렇죠. 그래서 납품을 잘 생각해야 해요. 선생님, 납기는 어떻게 되죠?"),
(L, "Una parte puede salir de stock en dos semanas. El resto se fabrica bajo pedido: seis semanas de producción, más el transporte.", "일부는 재고에서 2주 안에 나갈 수 있어요. 나머지는 주문 생산이라 생산 6주에 운송 기간이 더해집니다."),
(R, "¿Y el barco, cuánto tarda?", "배는 얼마나 걸려요?"),
(L, "De Valencia a Altamira, unas tres semanas. Luego el camión hasta Monterrey.", "발렌시아에서 알타미라까지 3주쯤이요. 그다음 몬테레이까지 트럭이고요."),
(G, "O sea que, desde el pedido, unos tres meses para todo.", "그러니까 주문부터 전부 오는 데 석 달쯤이네요."),
(A, "Si el pedido se confirma pronto, sí. Las primeras entregas podrían salir antes.", "주문이 빨리 확정되면 그래요. 첫 물량은 그보다 일찍 나갈 수도 있어요."),
(G, "Eso me gusta. La obra no puede esperar, el vestíbulo se termina en julio.", "그거 좋네요. 공사는 기다릴 수 없거든요. 로비는 7월에 마무리돼요."),
(R, "Una cosa más, ya técnica: ¿el tono es el mismo en todas las piezas? Porque en el vestíbulo, con esa luz, se nota todo.", "하나만 더, 기술적인 거예요. 모든 타일 색조가 같나요? 로비는 조명 때문에 다 티가 나거든요."),
(A, "Cada lote tiene un tono y un calibre. Lo importante es que todo el vestíbulo salga del mismo lote. Eso se puede garantizar si se pide de una vez.", "로트마다 색조와 치수가 있어요. 중요한 건 로비 전체가 같은 로트에서 나오는 거예요. 한 번에 주문하면 보장할 수 있어요."),
(R, "Muy bien. Eso es justo lo que quería oír.", "아주 좋아요. 그게 제가 듣고 싶던 말이에요."),
(G, "Bueno, licenciado, ahora lo importante. ¿Cuánto me cuesta?", "자, 선생님, 이제 중요한 거요. 얼마예요?"),
(L, "Antes de darle una cifra, ¿me puede decir si necesita el precio en fábrica o con el transporte incluido?", "숫자를 드리기 전에, 공장 출고가가 필요하신지 운송 포함 가격이 필요하신지 말씀해 주시겠어요?"),
(G, "Puesto en Monterrey, por supuesto. Yo no sé nada de barcos. Quiero saber cuánto pago por metro cuadrado aquí, en mi bodega.", "몬테레이 도착가로요, 당연히. 전 배에 대해선 하나도 몰라요. 여기 제 창고에서 제곱미터당 얼마 내는지 알고 싶어요."),
(L, "¿En su bodega? ¿Su almacén, quiere decir?", "보데가요? 창고 말씀이세요?"),
(G, "Mi almacén, sí. (ríe) Allá bodega es para el vino, ¿verdad?", "네, 창고요. (웃으며) 그쪽에선 보데가가 와인 저장고죠?"),
(L, "Exacto. Mire, el precio en fábrica se lo puedo dar hoy, pero el precio puesto en Monterrey depende del flete, del seguro y de los impuestos de importación.", "맞아요. 공장 출고가는 오늘 드릴 수 있지만, 몬테레이 도착가는 운임, 보험, 수입세에 따라 달라집니다."),
(G, "Entonces deme una idea. Una cifra aproximada.", "그럼 대충이라도 알려 주세요. 대략적인 숫자요."),
(L, "Prefiero no darle una cifra que luego tenga que cambiar. Le envío una oferta formal con todos los costes.", "나중에 바꿔야 할 숫자는 드리고 싶지 않아요. 비용을 전부 넣은 정식 견적을 보내 드릴게요."),
(G, "Mire, licenciado, le voy a ser sincera. El italiano ya me mandó su precio. Puesto en Monterrey.", "저기요, 선생님, 솔직히 말씀드릴게요. 이탈리아 쪽은 벌써 가격을 보냈어요. 몬테레이 도착가로요."),
(L, "¿Puedo preguntarle cuánto?", "얼마인지 여쭤봐도 될까요?"),
(G, "Poder, puede. Pero no se lo voy a decir. (sonríe) Le digo solo que es más barato de lo que usted piensa.", "물어보실 순 있죠. 근데 말씀 안 드릴 거예요. (미소 지으며) 선생님 생각보다 싸다는 것만 말씀드릴게요."),
(R, "Pero la muestra del italiano tenía la veta más falsa. Se veía impresa, la verdad.", "근데 이탈리아 샘플은 결이 더 가짜 같았어요. 솔직히 인쇄한 티가 났어요."),
(G, "Rodolfo... (lo mira) No le dé argumentos al vendedor.", "로돌포… (그를 쳐다보며) 판매자한테 무기를 주지 마요."),
(L, "(sonríe) Demasiado tarde. Ya lo he oído.", "(웃으며) 이미 늦었어요. 들어 버렸어요."),
(G, "(ríe) Ni modo. Mire, me gusta su producto, y me gusta que no me prometa cosas que no sabe. Pero necesito tres cosas.", "(웃으며) 어쩔 수 없네요. 저기요, 제품도 마음에 들고 모르는 걸 약속하지 않는 것도 마음에 들어요. 근데 세 가지가 필요해요."),
(L, "Dígame.", "말씀하세요."),
(G, "Uno: una oferta formal, puesta en Monterrey, en dos semanas. No en ahorita. En dos semanas.", "하나, 몬테레이 도착가 정식 견적을 2주 안에요. '아오리타'가 아니라 2주요."),
(L, "Dos semanas. Entendido.", "2주요. 알겠습니다."),
(G, "Dos: más muestras. El antiderrapante para los baños y un tono un poquito más cálido. El arquitecto dice que este blanco es muy frío.", "둘, 샘플 더요. 욕실용 미끄럼 방지 제품하고 색조가 조금 더 따뜻한 거요. 건축가 말이 이 흰색은 너무 차갑대요."),
(A, "Más cálido... ¿Un blanco tirando a crema?", "더 따뜻하게… 크림빛이 도는 흰색이요?"),
(G, "Eso, algo así. Y tres: una pieza grande para el vestíbulo. Quiero ver una placa de las grandotas, de esas de tres metros.", "그거요, 그런 거. 그리고 셋, 로비용 대형 판이요. 그 3미터짜리 커다란 판 하나를 보고 싶어요."),
(L, "¿Una placa de tres metros como muestra?", "3미터짜리 판을 샘플로요?"),
(R, "Aunque sea un pedazo, licenciado. Pero que se vea el formato real, el grosor, cómo se corta.", "조각이라도 괜찮아요, 선생님. 실제 규격, 두께, 어떻게 잘리는지만 보이면요."),
(L, "Lo estudiamos con el equipo de diseño. Le confirmo la fecha de envío esta misma semana.", "디자인팀과 검토하겠습니다. 발송 날짜는 이번 주 안에 확인해 드릴게요."),
(G, "Perfecto. Entonces quedamos así. Y licenciado, ¿cómo se dice? Que le vaya bonito.", "좋아요. 그럼 그렇게 하기로 해요. 그리고 선생님, 뭐라고 하더라? 잘 지내세요."),
(L, "Igualmente, señora Garza. Ingeniero, muchas gracias por sus preguntas.", "선생님도요, 가르사 씨. 엔지니어님, 질문 감사했습니다."),
(R, "A usted. Y mande el antiderrapante, ¿eh? Que no se le olvide.", "저야말로요. 그리고 미끄럼 방지 꼭 보내 주세요. 잊지 마시고요."),
(None, "La pantalla se queda negra. Durante unos segundos nadie habla. Fuera ya es de noche.", "화면이 꺼진다. 몇 초 동안 아무도 말하지 않는다. 밖은 벌써 어둡다."),

("#", "Escena 3 · 18:20 · La misma sala", "장면 3 · 오후 6시 20분 · 같은 회의실"),
(L, "Bueno. ¿Qué te ha parecido?", "자. 어땠어요?"),
(A, "Que has dicho «no lo sé» cuatro veces.", "'모르겠다'는 말을 네 번 했다는 거요."),
(L, "Tres. Y las tres era verdad.", "세 번이요. 그리고 세 번 다 사실이었고요."),
(A, "Por eso no te he interrumpido. Ella también lo ha notado. Y le ha gustado.", "그래서 안 끼어들었어요. 그 사람도 알아챘어요. 그리고 좋아했고."),
(L, "¿Tú crees?", "그렇게 생각해요?"),
(A, "Una mujer que compra sesenta mil metros está harta de vendedores que lo saben todo.", "6만 제곱미터를 사는 여자는 뭐든 다 안다는 판매자에 질려 있어요."),
(L, "¿Y el ingeniero? Me ha parecido que estaba de nuestro lado.", "엔지니어는요? 우리 편인 것 같던데요."),
(A, "El ingeniero está del lado de la pieza que no le dé problemas en la obra. Si se los damos, lo perdemos.", "엔지니어는 현장에서 문제 안 일으키는 타일 편이에요. 우리가 문제를 일으키면 그 사람을 잃어요."),
(L, "Lo de la tarima casi me mata.", "타리마 얘기에서 죽을 뻔했어요."),
(A, "(casi sonríe) Ya. Apúntate otra: allí la bodega es el almacén.", "(웃을 뻔하며) 그러게요. 하나 더 적어요. 거기선 보데가가 창고예요."),
(L, "Apuntada. Ahora, lo serio: una placa de tres metros. ¿Eso se puede mandar como muestra?", "적었어요. 이제 진지한 얘기, 3미터짜리 판이요. 그걸 샘플로 보낼 수 있어요?"),
(A, "Se puede, pero no en un sobre. Necesita una caja de madera, y cuesta un dineral. Habla con Nuria; quizás un trozo de un metro sea suficiente.", "가능은 한데 봉투로는 안 되죠. 나무 상자가 필요하고 돈이 엄청 들어요. 누리아랑 얘기해 봐요. 1미터 조각이면 충분할지도 몰라요."),
(L, "¿Y el blanco más cálido?", "더 따뜻한 흰색은요?"),
(A, "Eso es diseño también. Nuria puede ajustar el color en la impresora. Pero si cambiamos el tono, ya no sale del stock: hay que fabricarlo.", "그것도 디자인 일이에요. 누리아가 프린터에서 색을 조정할 수 있어요. 근데 색조를 바꾸면 재고에서 못 나가요. 새로 만들어야 하죠."),
(L, "O sea, que lo que quiere el arquitecto obliga a encender el horno.", "그러니까 건축가가 원하는 걸 하려면 가마를 켜야 하는 거네요."),
(A, "Un horno, al menos. Y eso no lo decides tú ni yo.", "가마 하나는 최소한요. 그리고 그건 당신도 나도 결정할 수 없어요."),
(L, "Lo sé. Pero dos semanas es poco tiempo para tanta decisión.", "알아요. 그런데 그 많은 결정을 하기엔 2주는 짧아요."),
(A, "En esta empresa, dos semanas es mucho tiempo. Las cosas se deciden en una comida. (coge su carpeta) Mañana te paso el coste del lote. Esta noche, descansa.", "이 회사에서 2주는 긴 시간이에요. 일은 밥 한 끼에 결정되거든요. (서류철을 집으며) 내일 로트 원가 넘겨줄게요. 오늘 밤은 쉬어요."),
(L, "Amparo.", "암파로."),
(A, "¿Qué?", "왜요?"),
(L, "Gracias por lo del palé.", "팔레 얘기, 고마웠어요."),
(A, "(ya en la puerta) No me las des. Si sale mal, el problema también será mío.", "(벌써 문가에서) 고마워하지 마요. 잘못되면 그건 내 문제이기도 하니까."),
(None, "Lucas se queda solo. En la pizarra escribe tres palabras: «oferta», «antideslizante», «tres metros». Debajo, con letra más pequeña: «tarima = palé, bodega = almacén».", "루카스가 혼자 남는다. 화이트보드에 세 단어를 쓴다. '견적', '미끄럼 방지', '3미터'. 그 아래 작은 글씨로 '타리마 = 팔레, 보데가 = 창고'."),
]

